// Notificacao ao cliente sobre movimento na negociacao
const d = $json.data || $json;
const valor = d.amount_cents ? 'R$ ' + (d.amount_cents/100).toFixed(2).replace('.', ',') : '';
const textos = {
  'proposal.countered': `O profissional enviou uma contraproposta de ${valor}. Acesse a plataforma para aceitar, recusar ou contrapor.`,
  'proposal.rejected': 'O profissional recusou a proposta. Sua solicitacao continua aberta para outros tecnicos.',
};
return { json: { texto: textos[$json.event_type] || 'Atualizacao na sua negociacao.', comando: null, data: d } };
